#include <genesis.h>
#include "level2.h"
#include "resources.h"  // Generated by rescomp from your .res file

// Adjust these based on your sprite sheet frame sizes!
// Example: if frames are 48x64 pixels = 6x8 tiles
#define GRIZZLY_FRAME_W  6   // tiles
#define GRIZZLY_FRAME_H  8
#define QUICKY_FRAME_W   4   // tiles
#define QUICKY_FRAME_H   6

// Game constants
#define SCREEN_W  320
#define SCREEN_H  224
#define GROUND_Y  118
#define BOSS_MAX_HP  134
#define PLAYER_MAX_HP 200

static Sprite* playerSprite;
static Sprite* bossSprite;

static s16 playerX = 40;
static s16 playerY = GROUND_Y;
static s16 bossX = 220;
static s16 bossY = GROUND_Y - 15;
static u8 playerHP = PLAYER_MAX_HP;
static u8 bossHP = BOSS_MAX_HP;
static BossState bossState = BOSS_IDLE;
static PlayerState playerState = PLAYER_IDLE;
static u16 bossTimer = 0;
static bool playerFacingRight = TRUE;
static bool bossFacingLeft = TRUE;  // Boss faces player

// Simple AABB collision
static bool checkCollision(s16 x1, s16 y1, s16 w1, s16 h1, s16 x2, s16 y2, s16 w2, s16 h2) {
    return (x1 < x2 + w2 && x1 + w1 > x2 && y1 < y2 + h2 && y1 + h1 > y2);
}

static void updatePlayer(void) {
    u16 joy = JOY_readJoypad(JOY_1);
    s16 speed = 2;

    if (joy & BUTTON_LEFT) {
        playerX -= speed;
        playerFacingRight = FALSE;
        if (playerState != PLAYER_JUMP) playerState = PLAYER_WALK;
    } else if (joy & BUTTON_RIGHT) {
        playerX += speed;
        playerFacingRight = TRUE;
        if (playerState != PLAYER_JUMP) playerState = PLAYER_WALK;
    } else if (playerState == PLAYER_WALK) {
        playerState = PLAYER_IDLE;
    }

    if ((joy & BUTTON_A) && playerState != PLAYER_JUMP) {
        playerState = PLAYER_JUMP;
        // Simple jump: in real code use velocity + gravity
        playerY -= 40;
    }

    // Simple gravity return
    if (playerState == PLAYER_JUMP && playerY < GROUND_Y) {
        playerY += 2;
        if (playerY >= GROUND_Y) {
            playerY = GROUND_Y;
            playerState = PLAYER_IDLE;
        }
    }

    // Clamp position
    if (playerX < 10) playerX = 10;
    if (playerX > SCREEN_W - 40) playerX = SCREEN_W - 40;

    // Set animation (adjust indices to match your sprite sheet rows)
    u8 anim = 0;
    if (playerState == PLAYER_WALK) anim = 1;
    else if (playerState == PLAYER_JUMP) anim = 4;
    else if (playerState == PLAYER_ATTACK) anim = 8;

    SPR_setAnim(playerSprite, anim);
    SPR_setHFlip(playerSprite, !playerFacingRight);
    SPR_setPosition(playerSprite, playerX, playerY);
}

static void updateBoss(void) {
    bossTimer++;

    // Simple AI: chase player, occasional attack
    s16 dx = playerX - bossX;
    s16 dist = abs(dx);

    if (bossState == BOSS_IDLE || bossState == BOSS_WALK) {
        if (dist > 60) {
            // Walk towards player
            bossState = BOSS_WALK;
            if (dx > 0) {
                bossX += 1;
                bossFacingLeft = FALSE;
            } else {
                bossX -= 1;
                bossFacingLeft = TRUE;
            }
        } else {
            bossState = BOSS_IDLE;
            // Chance to attack
            if (bossTimer % 120 == 0) {
                bossState = BOSS_ATTACK;
                bossTimer = 0;
            }
        }
    } else if (bossState == BOSS_ATTACK) {
        if (bossTimer > 30) {
            // Attack hitbox active briefly
            if (checkCollision(bossX - 20, bossY, 80, 60, playerX, playerY, 32, 48)) {
                if (playerHP > 0) playerHP--;
                // Flash or hurt effect here
            }
            bossState = BOSS_IDLE;
        }
    } else if (bossState == BOSS_HURT) {
        if (bossTimer > 20) bossState = BOSS_IDLE;
    }

    if (bossHP == 0) {
        bossState = BOSS_DEAD;
        // Play death anim, then end level
    }

    // Animations (adjust row indices to your sheet)
    u8 anim = 0; // idle
    if (bossState == BOSS_WALK) anim = 1;
    else if (bossState == BOSS_ATTACK) anim = 2;
    else if (bossState == BOSS_HURT) anim = 3;
    else if (bossState == BOSS_DEAD) anim = 1;

    SPR_setAnim(bossSprite, anim);
    SPR_setHFlip(bossSprite, bossFacingLeft);
    SPR_setPosition(bossSprite, bossX, bossY);
}

void showBossLevel(void) {
    // Init VDP
    VDP_setScreenWidth320();
    VDP_setPaletteColors(0, (u16*)palette_black, 64); // or load your palettes

    // Load background if you have one
    XGM_startPlay(boss_xgm);
    VDP_drawImage(BG_B, &boss_image, 0, 0);
    VDP_setTextPalette(PAL1);
    // VDP_loadTileSet(...);
    // VDP_setTileMapEx(...);

    // Init sprites
    SPR_init();

    // Add player (Quicky) - assumes resource named mascot_sprite
    PAL_setPalette(PAL3, mascot_sprite.palette->data, CPU);
    playerSprite = SPR_addSprite(&mascot_sprite, playerX, playerY,
                                 TILE_ATTR(PAL3, TRUE, FALSE, FALSE));

    // Add boss (Grizzly)
    PAL_setPalette(PAL2, grizzly_sprite.palette->data, CPU);
    bossSprite = SPR_addSprite(&grizzly_sprite, bossX, bossY,
                               TILE_ATTR(PAL2, TRUE, FALSE, FALSE));

    // Main loop
    while (bossState != BOSS_DEAD && playerHP > 0) {
        updatePlayer();
        updateBoss();

        // Player attack example (BUTTON_B)
        u16 joy = JOY_readJoypad(JOY_1);
        if (joy & BUTTON_B && playerState != PLAYER_ATTACK) {
            playerState = PLAYER_ATTACK;
            // Check if hit boss
            if (checkCollision(playerX, playerY, 40, 48, bossX, bossY, 64, 70)) {
                if (bossHP > 0) {
                    bossHP--;
                    bossState = BOSS_HURT;
                    bossTimer = 0;
                }
            }
        }

        // Draw HP (simple text)
        char buf[16];
        sprintf(buf, "HP:%d", playerHP);
        VDP_drawText(buf, 1, 1);
        sprintf(buf, "BOSS:%d", bossHP);
        VDP_drawText(buf, 20, 1);

        SPR_update();
        SYS_doVBlankProcess();  // or VDP_waitVSync()
    }

    // Cleanup
    SPR_releaseSprite(playerSprite);
    SPR_releaseSprite(bossSprite);
    XGM_stopPlay();
    SPR_end();

    if (playerHP == 0) {
        VDP_drawText("GAME OVER", 14, 12);
    } else {
        VDP_drawText("YOU WIN!", 14, 12);
    }
    waitMs(2000);
    SYS_reset();
}